import{_ as o,o as i,c as r,a0 as t}from"./chunks/framework.B6reNh8h.js";const u=JSON.parse('{"title":"Decisions","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/decisions.md","filePath":"explanation/decisions.md"}'),n={name:"explanation/decisions.md"};function a(s,e,c,d,l,p){return i(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="decisions" tabindex="-1">Decisions <a class="header-anchor" href="#decisions" aria-label="Permalink to &quot;Decisions&quot;">​</a></h1><p>ADR-lite — the decisions that shape pavo, the alternatives rejected, and the consequence each carries.</p><h2 id="declarative-ir-not-per-product-uis" tabindex="-1">Declarative IR, not per-product UIs <a class="header-anchor" href="#declarative-ir-not-per-product-uis" aria-label="Permalink to &quot;Declarative IR, not per-product UIs&quot;">​</a></h2><p><strong>Decision:</strong> drivers emit a ViewNode tree — data, not code — and hosts interpret it on every surface.</p><p><strong>Alternatives:</strong> each product ships its own TUI/web/CLI (UI silos, N surfaces × M products of code); embed a scripting language in drivers (untrusted-ish code on PATH becomes a host exploit).</p><p><strong>Consequence:</strong> one driver visualizes everywhere; the worst a buggy driver can do is emit a malformed tree, which degrades to KV. The cost: the IR can&#39;t express everything (rich interaction is v2) and drivers pay manifest+wire ceremony even for trivial views. See <a href="./why-declarative.html">Why declarative views</a>.</p><h2 id="additive-only-protocol-within-v1" tabindex="-1">Additive-only protocol within v1 <a class="header-anchor" href="#additive-only-protocol-within-v1" aria-label="Permalink to &quot;Additive-only protocol within v1&quot;">​</a></h2><p><strong>Decision:</strong> new optional fields, <code>kind</code> variants, and ops may appear at any time; existing spellings never change meaning. Forward compatibility is mandatory.</p><p><strong>Alternatives:</strong> versioned protocol revisions (<code>/v2</code> endpoints — every consumer must track versions); breaking changes allowed (surfaces and drivers drift apart on upgrade).</p><p><strong>Consequence:</strong> a driver written today keeps working as the IR grows; every consumer obligation (unknown kind → KV, open <code>props</code>, <code>extra</code> round-trip) follows from this one rule.</p><h2 id="drivers-are-executables-not-plugins" tabindex="-1">Drivers are executables, not plugins <a class="header-anchor" href="#drivers-are-executables-not-plugins" aria-label="Permalink to &quot;Drivers are executables, not plugins&quot;">​</a></h2><p><strong>Decision:</strong> a view provider is a <code>tamias-driver-*</code> binary on <code>PATH</code> speaking ndjson JSON-RPC — the tamias distribution mechanism, reused.</p><p><strong>Alternatives:</strong> in-process plugin API (ABI/version coupling, host crashes); per-product UIs again (see above); a daemon registry (pavo stays a per-user localhost bridge, no service).</p><p><strong>Consequence:</strong> installing visualization for a product is <code>tamias install</code> — no pavo-side registry, no plugin sandbox. <code>pavo-driver-kit</code> exists as an authoring convenience but is not a second contract.</p><h2 id="renderer-plugins-are-opt-in-claims-with-mandatory-fallback" tabindex="-1">Renderer plugins are opt-in claims, with mandatory fallback <a class="header-anchor" href="#renderer-plugins-are-opt-in-claims-with-mandatory-fallback" aria-label="Permalink to &quot;Renderer plugins are opt-in claims, with mandatory fallback&quot;">​</a></h2><p><strong>Decision:</strong> a driver may claim whole view <code>kind</code>s via manifest <code>renderers[]</code> and answer <code>render</code> with a canonical RenderModel — but failure always falls back to built-in interpretation.</p><p><strong>Alternatives:</strong> no escape hatch (the 90% IR becomes a ceiling); mandatory plugins for rich kinds (one bad plugin breaks every view of that kind).</p><p><strong>Consequence:</strong> rich visuals (<code>svg</code>, custom renderers) exist without letting plugins become a reliability liability — the second contract is kept honest by construction.</p><h2 id="chrome-is-contribution-slots-not-a-shell-api" tabindex="-1">Chrome is contribution slots, not a shell API <a class="header-anchor" href="#chrome-is-contribution-slots-not-a-shell-api" aria-label="Permalink to &quot;Chrome is contribution slots, not a shell API&quot;">​</a></h2><p><strong>Decision:</strong> products compose the shared screen by filling eight declared <code>contributes</code> slots; the host merges deterministically (priority → driver name → id).</p><p><strong>Alternatives:</strong> a plugin shell API where drivers draw arbitrary chrome (unbounded, unthemed); per-product pages (back to silos).</p><p><strong>Consequence:</strong> the platform emerges from independent drivers — ordering is stable, unknown slots round-trip via <code>extra</code>, and the web shell renders slots it knows while ignoring the rest.</p>',22)])])}const g=o(n,[["render",a]]);export{u as __pageData,g as default};
